    pm.globals.set("access_token", responseData.access_token);
    pm.globals.set("refresh_token", responseData.refresh_token);
    pm.globals.set("UsuarioID", responseData.usuarioID);
    console.log("Token guardado correctamente en la variable global 'token'");
}

